    res = []
    def bt(inicio, actual):
        if len(actual) == k:
            res.append(actual[:])
            return
        for i in range(inicio, n + 1):
            actual.append(i)
            bt(i + 1, actual)
            actual.pop()
    bt(1, [])
    return res

